import{_ as e,a0 as i,w as s,s as a,ao as l,I as r,x as o,a1 as u,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"小技巧：如何修复Lubuntu中的Docky混合错误 | LCTT x X-CMD","titleTemplate":false,"description":"小技巧：如何修复Lubuntu中的Docky混合错误 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"小技巧：如何修复Lubuntu中的Docky混合错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"小技巧：如何修复Lubuntu中的Docky混合错误 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141112 [Quick Tip] How To Fix Docky Compositing Error In Lubuntu","title":"小技巧：如何修复Lubuntu中的Docky混合错误","tag":"201411","desc":""},"relativePath":"201411/20141112 [Quick Tip] How To Fix Docky Compositing Error In Lubuntu.md","filePath":"[post].md"}'),d={name:"201411/20141112 [Quick Tip] How To Fix Docky Compositing Error In Lubuntu.md"};function m(g,t,k,c,T,D){const n=i("Link");return s(),a("div",null,[t[13]||(t[13]=l(`<h1 id="小技巧-如何修复lubuntu中的docky混合错误" tabindex="-1">小技巧：如何修复Lubuntu中的Docky混合错误 <a class="header-anchor" href="#小技巧-如何修复lubuntu中的docky混合错误" aria-label="Permalink to “小技巧：如何修复Lubuntu中的Docky混合错误”">​</a></h1><p>总所周知，<strong>Docky</strong>是Unix/Linux类系统中的轻量级应用启动器。我是 Lubuntu 和 Docky 的忠实粉丝，因为它们不需要占用我的所有系统资源，这样就可以同时运行更多应用。我在笔记本上使用Docky应用启动器，系统为Lubuntu 14.04.</p><p>但是，如果你使用LXDE发行版，你也许肯定遇到过使用Docky时报混合的错误。看下面的截图。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/Docky.png" alt=""></p><p>如果不开启混合功能，就不能使用Docky一些特别功能，如3D背景、自动隐藏。如果你想开启这些Docky的功能，那么你需要在你的LXDE系统中开启混合功能。</p><p>就像这样，首先安装 <strong>xcompmgr</strong>包：</p><pre><code>sudo apt-get install xcompmgr
</code></pre><p>然后，选择<strong>菜单（Menu） -&gt; 偏好（Preferences） -&gt; LXSession默认程序（Default applications for LXSession）</strong>。选择自动开始（Autostart）选项卡。 在<strong>（+增加）+Add</strong>框中输入“<strong>@xcompmgr -n</strong>”不带引号。最后点击增加按钮。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/LXSession-configuration_002.png" alt=""></p><p>这样就搞定了。关掉LXSession配置窗口，注销或重启系统。之后，你就可以看见混合功能已经打开。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/unknown_006.png" alt=""></p><p>这时，你就可以使用3D背景和隐藏功能，如自动隐藏（Auto-hide），Intellihide和窗口闪烁（Window dodge）等。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/Docky-Settings_003.png" alt=""></p><p>搞定！干杯！</p><hr>`,15)),r("p",null,[t[1]||(t[1]=o("via: ",-1)),u(n,{href:"http://www.unixmen.com/quick-tip-fix-docky-compositing-error-lubuntu/"},{default:p(()=>[...t[0]||(t[0]=[o("http://www.unixmen.com/quick-tip-fix-docky-compositing-error-lubuntu/",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=o("作者：",-1)),u(n,{href:"http://www.unixmen.com/author/sk/"},{default:p(()=>[...t[2]||(t[2]=[o("SK",-1)])]),_:1}),t[6]||(t[6]=o(" 译者：",-1)),u(n,{href:"http://www.vicyu.net"},{default:p(()=>[...t[3]||(t[3]=[o("Vic020/VicYu",-1)])]),_:1}),t[7]||(t[7]=o(" 校对：",-1)),u(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=o("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原创翻译，",-1)),u(n,{href:"http://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[o("Linux中国",-1)])]),_:1}),t[12]||(t[12]=o(" 荣誉推出",-1))])])}const w=e(d,[["render",m]]);export{x as __pageData,w as default};
